        if state.mulligan.is_some() && !crate::setup::mulligan_owed(state).contains(&other) {
            out.push((ANSWERED_MULLIGAN_ACTION, other, ActionBody::Mulligan { keep: Vec::new() }));
        }
    }
    out
}
